import pandas as pd


def run(inputs: dict[str, "pd.DataFrame"]) -> dict[str, "pd.DataFrame"]:
    accounts = inputs["accounts"]
    txns = inputs["txns"]

    # Only consider txns whose account_id exists in accounts.
    df = txns.merge(accounts, on="account_id", how="inner")

    # Stable sort by account, then txn_ts, then txn_id to reproduce the
    # cursor's ORDER BY txn_ts, txn_id within each account.
    df = df.sort_values(
        by=["account_id", "txn_ts", "txn_id"], kind="mergesort"
    ).reset_index(drop=True)

    ledger_rows = []
    fee_rows = []

    FEE_AMOUNT = 35.00

    for acc_id, group in df.groupby("account_id", sort=False):
        bal = float(group["opening_balance"].iloc[0])
        last_fee_date = None  # dates are non-decreasing within a group

        for row in group.itertuples(index=False):
            amount = row.amount
            txn_id = row.txn_id
            txn_ts = row.txn_ts

            bal = bal + amount

            if amount < 0 and bal < 0:
                fee_date = txn_ts.date() if hasattr(txn_ts, "date") else pd.Timestamp(txn_ts).date()
                if fee_date != last_fee_date:
                    bal = bal - FEE_AMOUNT
                    fee_rows.append(
                        {
                            "account_id": acc_id,
                            "fee_date": pd.Timestamp(fee_date),
                            "trigger_txn_id": txn_id,
                        }
                    )
                    last_fee_date = fee_date

            ledger_rows.append({"txn_id": txn_id, "balance_after": bal})

    txn_ledger = pd.DataFrame(ledger_rows, columns=["txn_id", "balance_after"])
    if len(txn_ledger) > 0:
        txn_ledger["txn_id"] = txn_ledger["txn_id"].astype("int64")
        txn_ledger["balance_after"] = txn_ledger["balance_after"].astype("float64")
    else:
        txn_ledger = pd.DataFrame(
            {
                "txn_id": pd.Series(dtype="int64"),
                "balance_after": pd.Series(dtype="float64"),
            }
        )

    fees = pd.DataFrame(
        fee_rows, columns=["account_id", "fee_date", "trigger_txn_id"]
    )
    if len(fees) > 0:
        fees["account_id"] = fees["account_id"].astype("int64")
        fees["fee_date"] = pd.to_datetime(fees["fee_date"])
        fees["trigger_txn_id"] = fees["trigger_txn_id"].astype("int64")
    else:
        fees = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "fee_date": pd.Series(dtype="datetime64[us]"),
                "trigger_txn_id": pd.Series(dtype="int64"),
            }
        )

    return {"txn_ledger": txn_ledger, "fees": fees}
